<template>
 <view class="page" :class="{directory:!draft && !record && selectingSpread,'ritual-page':draft || record}">
  <view class="reading-header" :class="{compact:!draft&&!record&&!selectingSpread}"><button v-if="draft || record || !selectingSpread" class="text-button parent-back" aria-label="返回上一级" @tap="back">‹</button><view class="heading"><text v-if="draft || record" class="header-meta">{{ draft?.dailyDate || record?.dailyDate || '你的牌桌' }}</text><text v-if="!draft&&!record&&!selectingSpread" class="header-meta">{{currentSpread.positions.length}} 张牌</text><text class="title">{{ !draft && !record && selectingSpread ? '选一个，开始抽牌。' : (selectedScene?.spreadId === currentSpread.id && !record ? selectedScene.name : currentSpread.name) }}</text></view><button v-if="draft || record" class="text-button selector-link ritual-selector" @tap="showSelector">选择牌阵</button></view>
  <template v-if="!draft && !record">
   <template v-if="selectingSpread">
    <text class="muted intro">从你在意的事开始，也可以自由抽一组牌。</text>
    <button class="daily-tile" @tap="openDaily"><image v-if="directoryDaily" class="daily-cover" :class="{reversed:directoryDaily.reversed}" :src="cardImage(directoryDaily.id)" mode="aspectFit"/><view v-else class="daily-orbit">☾</view><view class="daily-copy"><text class="daily-label">{{localDate()}} · 塔罗日运</text><text class="daily-name">{{directoryDaily ? directoryDaily.name+' · '+(directoryDaily.reversed?'逆位':'正位') : '塔罗日运'}}</text><text class="daily-message">{{directoryDaily?.message || (store.dailyDraft ? '继续今天的日签' : '抽今天的牌')}}</text></view><text class="spread-arrow">→</text></button>
    <button v-if="store.draft" class="reading-resume" @tap="resume"><view><text class="resume-title">{{store.draft.phase==='read'?'查看当前牌局':'继续当前抽牌'}}</text><text class="resume-copy">{{getSpread(store.draft.spreadId).name}} · 已选 {{store.draft.picked.length}} / {{getSpread(store.draft.spreadId).positions.length}}</text></view><text class="spread-arrow">→</text></button>
    <view class="theme-nav" role="navigation" aria-label="快速找到牌阵"><button v-for="group in sceneGroups" :key="group.id" class="theme-chip" :class="{active:activeGroup===group.id}" @tap="scrollToGroup(group.id)">{{group.label}}</button></view>
    <view class="spread-list"><view v-for="group in sceneGroups" :key="group.id" :id="'spread-group-'+group.id" class="spread-group"><view class="catalog-section"><text>{{group.label}}</text><text class="group-count">{{group.scenes.length}}</text></view><view class="spread-options"><button v-for="scene in group.scenes" :key="scene.id" class="spread-item" @tap="chooseScene(scene)"><view class="spread-thumb spread-thumbnail" aria-hidden="true"><view v-for="(style,j) in thumbCards(scene.spreadId)" :key="j" class="thumbnail-card" :style="style"></view></view><view class="spread-copy"><text class="name">{{scene.name}}</text><text class="small muted scene-summary">{{shortDescription(scene.description)}}</text><text class="small count">{{getSpread(scene.spreadId).positions.length}} 张牌</text></view><text class="spread-arrow">→</text></button></view></view></view>
   </template>
   <view v-else class="setup">
    <text class="muted intro">{{ selectedScene?.description || currentSpread.summary }}</text>
    <view class="spread-guide"><text class="guide-heading">每张牌代表什么</text><view class="setup-diagram-mat"><view class="setup-diagram" :style="boardStyle"><view v-for="(p,i) in currentSpread.positions" :key="p.id" class="setup-cell" :style="cellStyle(i)"><view class="setup-slot"><text>{{i+1}}</text></view><text class="setup-label">{{p.label}}</text></view></view></view><view class="position-list"><view v-for="(p,i) in currentSpread.positions" :key="p.id" class="position-item"><text class="position-number">{{i+1}}</text><view><text class="position-title">{{p.label}}</text><text class="position-description">{{p.question}}</text></view></view></view></view>
    <view v-if="!selectedScene && currentSpread.topics?.length > 1" class="topics"><button v-for="t in topicOptions" :key="t.id" :class="{ active: topic === t.id }" @tap="topic = t.id">{{ t.label }}</button></view><view v-if="selectedScene?.question" class="preset-question"><text class="preset-label">可以这样提问</text><text class="preset-copy">{{selectedScene.question}}</text></view><text class="label">想问得更具体？可以写在这里。</text><textarea v-model="question" maxlength="3000" auto-height :placeholder="selectedScene?.questionExample || ('例如：' + (selectedScene?.question || currentSpread.bestFor || '关于我最近在意的事，这组牌能带来哪些思考？'))" class="question"/><text class="question-hint">不填写，就按牌阵给你一些一般提示。</text><button class="primary" @tap="start">{{ existingSpreadDraft ? '回到当前牌局' : '开始抽牌' }}</button>
   </view>
  </template>
  <template v-else-if="draft && (draft.phase !== 'read' || revealing) && !record">
   <text v-if="draft.question" class="question-summary">{{ draft.question }}</text>
   <view class="ritual-steps"><view v-for="(label,i) in ['洗牌','切牌','选牌','揭牌']" :key="label" class="ritual-step" :class="{active:ritualStep === i,done:ritualStep > i}"><text class="step-number">{{ i+1 }}</text><text>{{ label }}</text></view></view>
   <view class="panel ritual-panel" :class="[`phase-${draft.phase}`, {revealing}]" :style="motionStyle">
    <template v-if="['shuffle','shuffling'].includes(draft.phase)">
     <text class="section ritual-title">想一想，这次最想弄清什么。</text>
     <view :key="motionRun" class="shuffle-table" :class="{mixing:draft.phase==='shuffling',paused}"><view class="ritual-orbit"></view><view v-for="n in 18" :key="n" class="ritual-back shuffle-card" :style="shuffleStyle(n)"></view></view><view v-if="draft.phase==='shuffling'" :key="`label-${motionRun}`" class="shuffle-stage-label" :class="{paused}" aria-hidden="true"><text class="shuffle-label">摊开牌组</text><text class="shuffle-label">打散混洗</text><text class="shuffle-label">收拢牌叠</text></view>
     <button v-if="paused" class="primary" @tap="resumeMotion">继续洗牌</button><button v-else-if="draft.phase === 'shuffle'" class="primary" @tap="shuffle">开始洗牌</button><text v-else class="small muted ritual-status" role="status">正在洗牌…</text>
    </template>
    <template v-else-if="['cut','cutting'].includes(draft.phase)">
     <text class="section ritual-title">{{ draft.phase === 'cut' ? '点一叠，把它放到最上面。' : '正在收齐牌组' }}</text>
     <view :key="`cut-${motionRun}`" class="cut-table" :class="{gathering:draft.phase==='cutting',paused}"><view class="ritual-orbit"></view><button v-for="(offset,i) in [0,26,52]" :key="offset" class="cut-pile" :class="{chosen:cutChoice===i}" :style="{'--pile':i}" :disabled="draft.phase !== 'cut'" :aria-label="`选择第 ${i+1} 叠牌`" @tap="cut(offset,i)"><view v-for="layer in 4" :key="layer" class="ritual-back cut-back" :style="{'--layer':layer-1}" aria-hidden="true"></view><text class="pile-label">{{['左侧','中间','右侧'][i]}}</text></button></view><text class="muted ritual-status" role="status">{{paused ? '切牌已暂停' : draft.phase==='cut' ? '按自己的感觉选就好。' : '牌叠正在合拢…'}}</text>
     <button v-if="paused" class="primary" @tap="resumeMotion">继续切牌</button>
    </template>
    <template v-else>
     <view class="row selection-heading"><text class="section">{{ ['reveal','read'].includes(draft.phase) ? (revealing ? '牌面正在展开…' : draft.dailyDate ? '揭开今天的牌' : '选好了，揭开这组牌。') : `选第 ${draft.picked.length + 1} 张 · ${currentSpread.positions[draft.picked.length]?.label || ''}` }}</text><text v-if="draft.phase==='pick'" class="muted ritual-count">{{ draft.picked.length }} / {{ currentSpread.positions.length }}</text></view>
     <text v-if="draft.phase==='pick'" class="pick-copy">左右滑动挑选，确认后放入牌位。</text>
     <view v-if="draft.phase==='pick' && showGuide" class="pick-guide"><view><text class="guide-title">整副 78 张牌都可以选择。</text><text class="small">左右滑动，双指放大查看序号；轻点后再确定。</text></view><button class="text-button" @tap="dismissGuide" aria-label="关闭选牌提示">×</button></view>
     <view class="board" :class="'layout-'+currentSpread.layout" :style="boardStyle"><view v-for="(p,i) in currentSpread.positions" :key="p.id" class="slot" :class="[`slot-${i}`, {current:draft.picked.length===i}]" :style="cellStyle(i)"><view class="slot-back" :class="{ filled: draft.picked[i] !== undefined, arriving: arrivingSlot === i }"><text>{{ i + 1 }}</text><text v-if="draft.picked[i] !== undefined" class="star">✦</text></view><text class="slot-label">{{i+1}} · {{ p.label }}</text></view></view>
     <template v-if="draft.phase === 'pick'">
      <ContinuousFan :picked="draft.picked" :disabled="pending !== null || flying !== null" :initial-offset="draft.fanOffset || 0" :initial-zoom="draft.fanZoom || 1" :skip-intro="draft.fanIntroSeen===true" @introduced="markFanIntroduced" @choose="chooseCard" @viewport-change="updateFanViewport"/>
     </template>
     <button v-if="draft.phase === 'reveal'" class="primary" :disabled="revealing || !!flying" @tap="reveal">{{ revealing ? '牌面正在展开…' : draft.dailyDate ? '揭开今天的牌' : '揭牌并查看解读' }}</button>
     <button v-if="draft.picked.length" class="text-button undo" :disabled="!!flying || revealing" @tap="undo">撤回刚选的一张</button>
    </template>
   </view>
   <view v-if="pending !== null" class="pending-mask" @tap="changeCard"><view class="pending-sheet" role="dialog" aria-modal="true" tabindex="-1" aria-label="确认选牌" @tap.stop><text class="small muted">{{ draft.picked.length+1 }} · {{ currentSpread.positions[draft.picked.length]?.label }}</text><text class="section">就选这一张？</text><view class="ritual-back pending-back"><view class="card-inner" aria-hidden="true"></view></view><button class="primary" @tap="confirmCard">确定</button><button class="text-button change-card" @tap="changeCard">换一张</button></view></view>
   <view v-if="flying" class="ritual-back flying-back" :style="flying"><view class="card-inner" aria-hidden="true"></view></view>

  </template>
  <template v-else-if="record && (day || result)">
   <view v-if="day" class="daily-result daily-almanac" :data-daily-date="day.date" aria-label="塔罗日运">
    <view class="daily-masthead"><view class="daily-masthead-copy"><text class="daily-edition">秘境梦屿</text><text class="daily-title">塔罗日运</text><text class="daily-dedication">一日一签，留一点时间给自己。</text></view><view class="daily-calendar"><text class="daily-month">{{ day.year }} / {{ day.month }}</text><text class="daily-calendar-day">{{ day.day }}</text><text class="daily-weekday">{{ day.weekday }}</text></view><text class="daily-celestial" aria-hidden="true">☾ · ✦</text></view>
    <view class="daily-paper">
     <view class="daily-card-and-signs"><view class="daily-portrait"><button class="daily-card-cover" aria-label="放大牌面" @tap="previewDaily"><image :src="cardImage(day.id)" :class="{ reversed:day.reversed }" mode="widthFix" class="daily-card-image"/><view class="daily-zoom" aria-hidden="true"><view class="daily-zoom-lens"/></view></button><view class="daily-caption"><text class="daily-card-name">{{ day.name }}</text><text class="daily-orientation">{{ day.reversed ? '逆位' : '正位' }}</text></view></view><view class="daily-signs"><view class="daily-sign daily-do"><text class="daily-sign-mark">宜</text><text class="daily-sign-copy">{{ day.do }}</text></view><view class="daily-sign daily-avoid"><text class="daily-sign-mark">忌</text><text class="daily-sign-copy">{{ day.avoid }}</text></view><text class="daily-sign-note">顺着牌意，照顾今天。</text></view></view>
     <view class="daily-message"><text class="daily-heading">今天，把注意力放在这里。</text><text class="daily-core">{{ day.core }}</text></view>
     <view class="daily-advice"><text class="daily-heading">一件可以尝试的事</text><text class="daily-paragraph">{{ day.advice }}</text><text class="daily-small">选择其中一件与你实际生活有关的小事，今晚再看看发生了什么。</text></view>
     <view class="daily-reference"><button class="daily-reference-toggle" :aria-expanded="dailyReferenceOpen" @tap="dailyReferenceOpen=!dailyReferenceOpen"><text>{{ dailyReferenceOpen ? '▾' : '▸' }} 查看这张牌的依据</text></button><view v-if="dailyReferenceOpen" class="daily-reference-body"><text class="daily-paragraph">{{ day.observation }}</text><text class="daily-small">宜忌是这张牌的生活提醒，不是传统黄历的吉凶择日。</text><button class="text-button daily-reference-link" @tap="openCard(day.id)">查看单牌完整释义</button></view></view>
     <view class="daily-footer"><view class="daily-retention"><text class="daily-star" aria-hidden="true">✦</text><text>今天重新打开，仍是这张牌。日运只保留到当天结束。</text></view><button class="primary wide" @tap="showSelector">返回抽牌首页　→</button></view>
    </view>
   </view>
   <template v-else-if="result">
   <text v-if="record.question" class="question-summary">{{ record.question }}</text>
   <view class="board result-board" :class="[{fresh:freshResult},'layout-'+currentSpread.layout]" :style="boardStyle"><view v-for="(c,i) in record.cards" :key="c.id" class="slot" :style="cellStyle(i)"><image :src="cardImage(c.id)" mode="aspectFit" class="face" :style="{animationDelay:`${i*120}ms`}" :class="{ reversed:c.reversed }" @tap="openCard(c.id)"/><text class="slot-label">{{ i+1 }} · {{ currentSpread.positions[i].label }}</text><text class="small muted">{{ cardName(c.id) }} · {{ c.reversed ? '逆位' : '正位' }}</text></view></view>
   <view v-if="result.display !== 'positions'" class="panel"><text class="section">{{ result.overview.title }}</text><text class="paragraph">{{ result.overview.text }}</text></view>
   <view v-for="p in result.positions" :key="p.positionId" class="panel reading-card"><view class="reading-title"><image :src="cardImage(p.cardId)" mode="aspectFit" class="reading-face" :class="{ reversed:p.orientation === 'reversed' }" @tap="openCard(p.cardId)"/><view><text class="section">{{ p.positionLabel }}</text><text class="muted">{{ p.cardName }} · {{ p.orientation === 'reversed' ? '逆位' : '正位' }}</text></view></view><text class="message">暗语 · {{ p.message }}</text><text class="paragraph">{{ p.coreMeaning }}</text><text class="paragraph">{{ p.orientationMeaning }}</text><view v-for="(detail,i) in p.details || []" :key="i"><text class="detail-title">{{ detail.title }}</text><text v-for="(paragraph,j) in detail.paragraphs" :key="j" class="paragraph">{{ paragraph }}</text></view></view>
   <view v-if="result.display !== 'positions' && result.sections?.length" class="panel"><view v-for="s in result.sections" :key="s.id"><text class="detail-title">{{ s.title }}</text><text class="paragraph">{{ s.text }}</text></view></view>
   <text class="small muted note">依据牌义、牌位与正逆位整理的本地解读，供你思考和参考。</text>
   <button class="secondary wide" @tap="showSelector">再选一个牌阵</button>
   </template>
  </template>
  <view v-else-if="record" class="panel"><text class="section">暂时无法显示这次解读</text><text class="paragraph">当前牌局仍然保留，可以重新进入抽牌页重试。</text><button class="secondary wide" @tap="showSelector">返回牌阵</button></view>
 </view>
  <view v-if="dailyZoomOpen && day" class="daily-zoom-backdrop" role="dialog" aria-modal="true" aria-label="放大牌面" @tap="dailyZoomOpen=false"><button class="daily-zoom-close" aria-label="关闭放大" @tap.stop="dailyZoomOpen=false">×</button><image class="daily-zoom-image" :class="{reversed:day.reversed}" :src="cardImage(day.id)" mode="aspectFit" @tap.stop/></view>
  <FloatingNavigation active="draw" />
</template>
<script setup lang="ts">
import ContinuousFan from '../../components/ContinuousFan.vue'
import {thumbnailGeometry} from '../../styles/generated/spread-thumbnail.mjs'
import { hideNativeTabBar } from '../../core/navigation'
onShow(hideNativeTabBar)

import { computed,ref,getCurrentInstance,nextTick,onMounted,onBeforeUnmount } from 'vue'
import { onShow,onHide,onUnload,onBackPress } from '@dcloudio/uni-app'
import { deck } from '../../core/catalogs'
import { readStore,writeStore,cardImage,notify,loadReadingStore } from '../../core/platform'
import { availableScenes,isProfessionalScene,beginShuffle,beginCut,finishMotion,SHUFFLE_MS,CUT_MS,blankReading,normalizeReading,currentRecord,todayReading,createDraft,pickCard,finishReading,dailyDisplay,interpretRecord,getSpread,boardLayout,localDate,READING_KEY,ENTRY_KEY } from '../../core/drawing'
import type { Draft,RecordItem,ReadingStore } from '../../core/drawing'
const store=ref<ReadingStore>(blankReading()),draft=ref<Draft|null>(null),record=ref<RecordItem|null>(null),chosen=ref('one'),question=ref(''),blocked=ref(false),topic=ref('general')
const returnToDraft=ref(false)
const selectingSpread=ref(true),selectedScene=ref<any>(null),pending=ref<number|null>(null),showGuide=ref(false),paused=ref(false),cutChoice=ref(-1),flying=ref<any>(null),arrivingSlot=ref(-1),revealing=ref(false),freshResult=ref(false)
const instance=getCurrentInstance()
const motionRun=ref(0)
const motionStyle=computed(()=>{const d=draft.value,total=d?.phase==='cutting'?CUT_MS:SHUFFLE_MS;return{'--motion-duration':`${SHUFFLE_MS}ms`,'--motion-elapsed':`${Math.max(0,total-(d?.motionRemaining??total))}ms`}})
const GUIDE_KEY='tarot-miniapp-pick-guide-v1'
let motionTimer:ReturnType<typeof setTimeout>|null=null,motionEnd=0,flightTimer:ReturnType<typeof setTimeout>|null=null,revealTimer:ReturnType<typeof setTimeout>|null=null
// #ifdef H5
let previousFocus:HTMLElement|null=null
function modalKeys(e:KeyboardEvent){if(dailyZoomOpen.value&&e.key==='Escape'){e.preventDefault();dailyZoomOpen.value=false;return}if(pending.value===null)return;if(e.key==='Escape'){e.preventDefault();changeCard();return}if(e.key==='Tab'){const nodes=Array.from(document.querySelectorAll<HTMLElement>('.pending-sheet button,.pending-sheet uni-button,.pending-sheet [tabindex]')).filter(x=>!x.hasAttribute('disabled')&&x.getAttribute('aria-disabled')!=='true');if(!nodes.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement?.classList.contains('pending-sheet'))){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}
function pageVisibility(){if(document.visibilityState==='hidden')stopVisuals()}
onMounted(()=>{document.addEventListener('keydown',modalKeys);document.addEventListener('visibilitychange',pageVisibility)})
onBeforeUnmount(()=>{document.removeEventListener('keydown',modalKeys);document.removeEventListener('visibilitychange',pageVisibility)})
// #endif
function sceneGroup(scene:any){if(isProfessionalScene(scene.id))return '通用与专业牌阵';return ({all:'常用牌阵',love:'感情',work:'工作',study:'学业',life:'生活'} as Record<string,string>)[scene.category] || '常用牌阵'}
const activeGroup=ref('all')
const sceneGroups=computed(()=>[['all','常用牌阵'],['love','感情'],['work','工作'],['study','学业'],['life','生活'],['professional','专业通用']].map(([id,label])=>({id,label,scenes:availableScenes.filter(scene=>id==='professional'?isProfessionalScene(scene.id):!isProfessionalScene(scene.id)&&scene.category===id)})))
const directoryDaily=computed(()=>dailyDisplay(todayReading(store.value)))
function scrollToGroup(id:string){activeGroup.value=id;uni.pageScrollTo({selector:'#spread-group-'+id,duration:300,offsetTop:-120})}
function openDaily(){
 dailyReferenceOpen.value=false;dailyZoomOpen.value=false;stopVisuals();selectingSpread.value=false
 const today=localDate(),existing=todayReading(store.value)
 if(existing){try{const next={...store.value,active:'daily' as const};writeStore(READING_KEY,next);store.value=next}catch{notify('暂时无法保存入口，请检查储存空间');return}record.value=existing;draft.value=store.value.dailyDraft;return}
 record.value=null;draft.value=store.value.dailyDraft?.dailyDate===today?store.value.dailyDraft:createDraft('daily','',today)
 if(draft.value.phase==='shuffle'){beginShuffle(draft.value);if(save())runMotion();else paused.value=true}else{if(!save())return;if(['shuffling','cutting'].includes(draft.value.phase))paused.value=true;else if(draft.value.phase==='pick')loadGuide()}
}
const ritualStep=computed(()=>!draft.value?0:['shuffle','shuffling'].includes(draft.value.phase)?0:['cut','cutting'].includes(draft.value.phase)?1:draft.value.phase==='pick'?2:3)
function shortDescription(text:string){return text.split(/[。；]/)[0]+'。'}
function thumbCards(id:string){return thumbnailGeometry(boardLayout(getSpread(id)))}
function chooseScene(scene:any){if(selectedScene.value?.id!==scene.id)question.value='';selectedScene.value=scene;topic.value=scene.topic;chooseSpread(scene.spreadId)}
function shuffleStyle(n:number){const i=n-1;return{'--card-index':i,'--fan-x':`${(i-8.5)*20}rpx`,'--fan-y':`${(Math.abs(i-8.5)*3-15)*2}rpx`,'--fan-r':`${(i-8.5)*3}deg`,'--scatter-x':`${((i*7)%6-2.5)*70}rpx`,'--scatter-y':`${(Math.floor((i*7)%18/6)-1)*148}rpx`,'--scatter-r':`${(i*47)%240-120}deg`,'--mix-x':`${((i*11+5)%6-2.5)*70}rpx`,'--mix-y':`${(Math.floor((i*11+5)%18/6)-1)*148}rpx`,'--mix-r':`${(i*73)%260-130}deg`}}
function dismissGuide(){showGuide.value=false;try{writeStore(GUIDE_KEY,true)}catch{notify('引导偏好暂未保存')}}
function pauseMotion(){if(motionTimer){clearTimeout(motionTimer);motionTimer=null;if(draft.value){draft.value.motionRemaining=Math.max(0,motionEnd-Date.now());paused.value=true;motionRun.value++;save()}}}
function stopVisuals(){pauseMotion();if(flightTimer)clearTimeout(flightTimer);if(revealTimer)clearTimeout(revealTimer);flightTimer=null;revealTimer=null;pending.value=null;flying.value=null;arrivingSlot.value=-1;revealing.value=false}
function runMotion(){const d=draft.value;if(motionTimer||!d||!['shuffling','cutting'].includes(d.phase))return;paused.value=false;motionRun.value++;const remaining=d.motionRemaining ?? (d.phase==='shuffling'?SHUFFLE_MS:CUT_MS);motionEnd=Date.now()+remaining;motionTimer=setTimeout(()=>{motionTimer=null;if(draft.value!==d)return;finishMotion(d);if(save()&&d.phase==='pick')loadGuide()},remaining)}
function resumeMotion(){if(save())runMotion()}
function shuffle(){if(draft.value&&beginShuffle(draft.value)){if(save())runMotion();else paused.value=true}}
function cut(offset:number,i:number){if(draft.value&&beginCut(draft.value,offset)){cutChoice.value=i;if(save())runMotion();else paused.value=true}}
function loadGuide(){try{showGuide.value=!readStore(GUIDE_KEY,false)}catch{showGuide.value=true}}

const topicOptions=[{id:'general',label:'通用'},{id:'love',label:'感情'},{id:'career',label:'工作'},{id:'study',label:'学业'},{id:'life',label:'生活'}]
const day=computed(()=>dailyDisplay(record.value))
const dailyReferenceOpen=ref(false),dailyZoomOpen=ref(false)
function previewDaily(){if(day.value)dailyZoomOpen.value=true}
const existingSpreadDraft=computed(()=>{if(!returnToDraft.value)return false;const d=chosen.value==='daily'?store.value.dailyDraft:store.value.draft;return d&&d.spreadId===chosen.value&&d.question===question.value&&d.topic===topic.value})
const currentSpread=computed(()=>getSpread(record.value?.spreadId || draft.value?.spreadId || chosen.value))
