.daily-paper{padding:24px}.daily-card-and-signs{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);align-items:center;gap:24px}.daily-portrait{min-width:0}.daily-card-cover{position:relative;display:block;box-sizing:border-box;width:100%;max-width:220px;margin:auto;padding:5px;background:var(--paper);border:1px solid var(--control-line);border-radius:8px;box-shadow:var(--shadow-card);line-height:0;transition:transform 160ms var(--ease-settle)}.daily-card-cover:active{transform:scale(.98)}.daily-card-image{display:block;width:100%;height:auto;border-radius:3px}.daily-zoom{position:absolute;right:5px;bottom:5px;width:26px;height:26px;display:flex;align-items:center;justify-content:center;background:var(--paper);color:var(--accent);border-radius:50%;font:24px/1 var(--font-body)}.daily-zoom-lens{box-sizing:border-box;position:relative;width:12px;height:12px;border:1.5px solid currentColor;border-radius:50%;margin:-3px 3px 0 0}.daily-zoom-lens:before{content:'';position:absolute;width:6px;height:1.5px;background:currentColor;right:-5px;bottom:-3px;transform:rotate(45deg)}.daily-zoom-lens:after{content:'+';position:absolute;inset:0;text-align:center;font:10px/9px var(--font-body)}
.daily-zoom-backdrop{position:fixed;inset:0;z-index:2000;background:#211c26ee;display:flex;align-items:center;justify-content:center;padding:70px 20px 40px;box-sizing:border-box}.daily-zoom-image{width:100%;height:100%;max-width:700px}.daily-zoom-close{position:absolute;right:20px;top:20px;width:44px;height:44px;margin:0;padding:0;background:var(--paper);color:var(--accent);border:0;border-radius:50%;font:32px/44px var(--font-body)}
.daily-caption{display:flex;justify-content:center;align-items:baseline;flex-wrap:wrap;gap:5px 8px;margin-top:13px}.daily-card-name{font:500 23px/1.35 var(--font-display)}.daily-orientation{color:var(--muted);font-size:12px;white-space:nowrap}.daily-signs{min-width:0;align-self:center}.daily-sign{padding:0 0 17px}.daily-sign+.daily-sign{border-top:1px solid var(--line);padding-top:17px}.daily-sign-mark{box-sizing:content-box;display:flex;align-items:center;justify-content:center;width:36px;min-height:36px;border:1px solid currentColor;border-radius:50%;font:500 21px var(--font-display);color:var(--accent);margin-bottom:9px}.daily-avoid .daily-sign-mark{color:#7e4a3c}.daily-sign-copy{display:block;font:500 19px/1.55 var(--font-display);overflow-wrap:anywhere}.daily-sign-note{display:block;color:var(--muted);font-size:11px;line-height:1.6}
.daily-message{border-top:3px double var(--control-line);margin-top:25px;padding-top:19px}.daily-heading{display:block;font:500 13px/1.5 var(--font-body);color:var(--accent);margin:0 0 8px}.daily-core{display:block;font:500 23px/1.6 var(--font-display);overflow-wrap:anywhere}.daily-advice{border-top:1px solid var(--line);padding-top:18px;margin-top:19px}.daily-paragraph{display:block;font-size:15px;line-height:1.8;margin:8px 0}.daily-small{display:block;font-size:12px;line-height:1.7;color:var(--muted);margin-top:10px}
